import { planEarthPopulation } from './earth-population-update.js';
import { applyLocalEarthPopulation } from './earth-population-local.js';
import { formatPOP } from './surface-distribution-model.js';
const $=s=>document.querySelector(s);
export class EarthPopulationUI {
 constructor(surface){this.surface=surface;this.pending=null;this.abort=new AbortController();const options={signal:this.abort.signal};$('#population-update-preview-button').addEventListener('click',()=>this.preview(),options);$('#population-update-cancel').addEventListener('click',()=>{this.pending=null;$('#population-update-preview').hidden=true;},options);$('#population-update-confirm').addEventListener('change',()=>{$('#population-update-apply').disabled=!this.pending||!$('#population-update-confirm').checked;},options);$('#population-update-apply').addEventListener('click',()=>this.apply(),options);$('#population-update-diff').addEventListener('click',()=>{if(!this.pending)return;const a=this.surface.industry;a.download(JSON.stringify({kind:'earth-population-only-comparison',before:Object.fromEntries(Object.entries(this.pending.before.startingScenario.cells).map(([id,c])=>[id,c.populationPersons])),after:Object.fromEntries(Object.entries(this.pending.after.startingScenario.cells).map(([id,c])=>[id,c.populationPersons]))},null,2),'SPACE_earth_population_comparison.json');},options);}
 refresh(){const s=this.surface,p=s.populationUpdatePackage,entry=s.entry;let available=!!p&&entry?.grid.systemId==='sol'&&entry.body.id==='earth'&&Object.keys(entry.template.startingScenario.cells).length===92;if(available)available=Object.entries(p.after.populationPersons).some(([id,n])=>entry.template.startingScenario.cells[id]?.populationPersons!==n);$('#surface-population-update').hidden=!available;if(this.pending&&this.pending.entry!==entry){this.pending=null;$('#population-update-preview').hidden=true;}}
 preview(){try{const s=this.surface,before=s.entry.template,after=planEarthPopulation(before,s.populationUpdatePackage);this.pending={entry:s.entry,before,after,baseJSON:JSON.stringify(before)};$('#population-update-preview').hidden=false;$('#population-update-confirm').checked=false;$('#population-update-apply').disabled=true;const rows=Object.keys(after.startingScenario.cells).sort().map(id=>`${id}: ${formatPOP(before.startingScenario.cells[id].populationPersons)} → ${formatPOP(after.startingScenario.cells[id].populationPersons)}`);$('#population-update-comparison').textContent=rows.join('\n');$('#population-update-status').textContent='공식 GHSL 2025 분포 · 총 8,893 POP. 인구 외 필드와 산업 진행을 보존하고 두 저장의 원본을 백업합니다. 이관 복원은 백업 파일로 진행하며 단일 표면 Undo와 분리합니다.';}catch(e){$('#population-update-status').textContent=e.message;}}
 apply(){const s=this.surface,p=this.pending;if(!p||!$('#population-update-confirm').checked)return;try{if(s.entry!==p.entry||JSON.stringify(s.entry.template)!==p.baseJSON)throw Error('미리보기 이후 초안이 달라졌습니다. 다시 비교하세요.');s.industry.sync();const result=applyLocalEarthPopulation({entry:s.entry,industry:s.industry,populationPackage:s.populationUpdatePackage,storage:s.drafts.storage});this.pending=null;$('#population-update-preview').hidden=true;s.distributions.invalidate();s.renderInfo();s.notify('공식 인구 92필드만 적용했습니다. 표면·산업 원본 백업과 기존 시설·재고·시간을 보존했습니다.');this.lastResult=result;}catch(e){$('#population-update-status').textContent='적용 거부 · 원본 보존: '+e.message;}}
 dispose(){this.abort.abort();}
}
